const EN=document.documentElement.lang==='en',T=(zh,en)=>EN?en:zh;
const buildings=[['R16','Arts Building','Arts 艺术楼','Red'],['R18','Strathcona Building','Strathcona 楼','Red'],['R13','Poynting Building','Poynting 楼','Red'],['Y3','Winifred Hackett Building','Winifred Hackett 楼','Yellow'],['Y9','Computer Science','计算机科学楼','Yellow'],['R25','Munrow Lecture Theatre (confirm room)','Munrow 阶梯教室（请确认房间）','Red'],['R6','Aston Webb – Great Hall (confirm block)','Aston Webb 大礼堂（请确认分区）','Red'],['R7','Aston Webb – Student Hub','Aston Webb 学生服务中心','Red'],['R5','Aston Webb – B Block','Aston Webb B 区','Red'],['R30','Main Library','主图书馆','Red'],['R32','Teaching and Learning Building','教学与学习大楼','Red']];
const areas=['Selly Oak','Birmingham City Centre','Harborne','Edgbaston','The Vale','Pritchatts Park Village'];
document.body.innerHTML=`<main class="shell"><header class="topbar"><a class="brand" href="#">↗ GreenGo <small>UoB</small></a><nav><a href="${EN?'index.html':'en.html'}">${EN?'中文':'English'}</a><a href="#map">${T('校园地图','Campus map')}</a></nav></header><section class="hero" style="min-height:330px;padding:50px 0"><div><p class="eyebrow">UNIVERSITY OF BIRMINGHAM · EDGBASTON</p><h1 style="font-size:48px">${T('从住处，<br>到具体的教室大楼。','From the starting area.<br>To the campus building.')}</h1><p class="lede">${T('把跨城区通勤与校园最后一段步行连起来，按课程时间安排出发。','Connect the commute with the final campus walk. Plan around the class time, not just the station.')}</p></div><aside class="impact-card"><p class="eyebrow">DOOR → CAMPUS → BUILDING</p><h2>${T('到大学站 ≠ 到教室','The station is not the classroom')}</h2><p>${T('目的地使用校园地图建筑编号；班次和时间使用可调整的演示情境。','Destinations use building codes from the campus map. Schedules and durations are adjustable demo scenarios.')}</p></aside></section><section class="plan-grid"><form class="route-card" id="commute"><p class="eyebrow">01 / COMMUTE PLANNER</p><h2>${T('今天去哪里上课？','Where is the class?')}</h2><label>${T('居住地区（情境示例）','Home area (scenario)')}<select id="area">${areas.map(a=>`<option>${a}</option>`).join('')}</select></label><label>${T('校园具体地点','Campus destination')}<select id="building">${buildings.map(b=>`<option value="${b[0]}">${b[0]} · ${EN?b[1]:b[2]+' / '+b[1]}</option>`).join('')}</select></label><div class="two-col"><label>${T('课程开始','Class starts')}<input type="time" id="classStart" value="10:00" required></label><label>${T('天气情境','Weather scenario')}<select id="sky"><option value="0">${T('晴天','Dry')}</option><option value="10">${T('下雨，增加 10 分钟','Rain, add 10 min')}</option></select></label></div><label>${T('通勤偏好','Commute preference')}<select id="preference"><option value="green">${T('低碳优先','Lower-carbon first')}</option><option value="fast">${T('耗时最短','Shortest duration')}</option><option value="few">${T('少换乘','Fewer transfers')}</option></select></label><label><input type="checkbox" id="accessible" style="width:auto"> ${T('需要无障碍路线核验','Require accessibility verification')}</label><details><summary>${T('调整班次与运行状态（演示）','Edit service scenarios')}</summary><label>${T('公交预计到站','Bus arrival')}<input type="time" id="bus" value="09:10" required></label><label>${T('火车预计到站','Train arrival')}<input type="time" id="train" value="09:15" required></label><label>${T('公交状态','Bus status')}<select id="busState"><option value="0">${T('正常','Normal')}</option><option value="10">${T('晚点 10 分钟','Delayed 10 min')}</option><option value="cancel">${T('停运','Cancelled')}</option></select></label><label>${T('火车状态','Train status')}<select id="trainState"><option value="0">${T('正常','Normal')}</option><option value="10">${T('晚点 10 分钟','Delayed 10 min')}</option><option value="cancel">${T('停运','Cancelled')}</option></select></label></details><button class="primary wide">${T('比较通勤方案','Compare commutes')} →</button></form><section><p class="eyebrow">02 / DEPARTURE & LAST MILE</p><div id="advice" class="recommendation" aria-live="polite"></div><div id="routes"></div></section></section><section class="planner" id="map"><p class="eyebrow">03 / CAMPUS WAYFINDING</p><h2>${T('抵达校园后的最后一段','The final campus connection')}</h2><p id="buildingNote"></p><p>${T('地图来源：提供的 Edgbaston Campus Map。建筑编号来自地图；本原型不绘制未经验证的导航路线。','Source: the supplied Edgbaston Campus Map. Building codes come from the map; unverified navigation paths are not drawn.')}</p><object data="assets/edgbaston-campus-map.pdf" type="application/pdf" width="100%" height="680"><a href="assets/edgbaston-campus-map.pdf">${T('打开校园地图 PDF','Open campus map PDF')}</a></object></section><section class="route-card"><h2>${T('数据与能力边界','Data and prototype scope')}</h2><p>${T('目前支持：地区与建筑选择、六类通勤比较、课前出发建议、晚点／停运和换乘可行性演示。所有通勤时长为设计假设，不是实际地理计算；没有接入实时天气、运营商、票价、课表或无障碍导航。','Available: area and building selection, six commute types, departure advice, delay/cancellation and transfer scenarios. Journey durations are design assumptions, not geographic calculations. Live weather, operators, fares, timetables and accessibility routing are not connected.')}</p><p>${T('计划接入：校园地图、天气变化、公交及火车班次和运行状态、单车点位、经核验的无障碍路线。','Planned: campus maps, changing weather, bus/train schedules and service status, bike stations, and verified accessible routes.')}</p></section><footer>GreenGo · University of Birmingham commute study · Demo</footer></main>`;
const $=id=>document.getElementById(id),minutes=s=>{const [h,m]=s.split(':').map(Number);return h*60+m},clock=n=>n<0||n>=1440?T('跨日情境','Different day'):String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
function update(){const b=buildings.find(x=>x[0]===$('building').value),area=$('area').value,idx=areas.indexOf(area),base=[18,32,26,24,22,16][idx],last={R16:12,R18:13,R13:15,Y3:10,R25:12,R7:15,R5:15,R30:10,R32:12,Y9:9,R6:14}[b[0]],weather=+$('sky').value,deadline=minutes($('classStart').value)-10;
const rows=[['walk',T('步行','Walk'),base+22,0],['cycle',T('骑行 + 步行','Cycle + walk'),Math.round(base*.65)+last,0],['bus',T('步行 + 公交 + 校园步行','Walk + bus + campus walk'),base+last,1],['train',T('步行 + 火车 + 校园步行','Walk + train + campus walk'),Math.round(base*.55)+last,1],['taxi',T('打车 + 校园步行','Taxi + campus walk'),Math.round(base*.6)+last,0],['combo',T('公交 + 火车 + 校园步行','Bus + train + campus walk'),base+last+10,2]].map(r=>{let leave=deadline-r[2]-weather,arrive=deadline,problem='';if(r[0]==='bus'||r[0]==='combo'){if($('busState').value==='cancel')problem=T('公交停运','Bus cancelled');else {const bus=minutes($('bus').value)+Number($('busState').value);leave=bus-8-weather;arrive=bus+base+last;}}
if(r[0]==='train'||r[0]==='combo'){if($('trainState').value==='cancel')problem=T('火车停运','Train cancelled');else{const train=minutes($('train').value)+Number($('trainState').value);if(r[0]==='train')leave=train-12-weather;else if(minutes($('bus').value)+Number($('busState').value||0)+base+5>train)problem=T('换乘时间不足','Insufficient transfer time');arrive=train+Math.round(base*.55)+last;}}
if(!problem&&arrive>deadline)problem=T('无法保留课前 10 分钟余量','Misses 10-minute class buffer');return {...{id:r[0],name:r[1],duration:arrive-leave,transfers:r[3],leave,arrive,problem}};});
const order=$('preference').value==='public'?['bus','train','combo','walk','cycle','taxi']:['walk','cycle','train','bus','combo','taxi'];
rows.sort((a,b)=>Number(!!a.problem)-Number(!!b.problem)||($('preference').value==='fast'?a.duration-b.duration:$('preference').value==='few'?a.transfers-b.transfers:order.indexOf(a.id)-order.indexOf(b.id)));
const best=rows.find(r=>!r.problem);$('advice').innerHTML=`<p>${area} → ${b[0]} · ${b[1]}</p><h2>${best?T('建议','Suggested')+' '+clock(best.leave):T('请调整班次','Adjust services')}</h2><p>${best?best.name+' · '+T('预计到达','Arrival')+' '+clock(best.arrive):T('当前情境无合适方案','No suitable option in this scenario')}</p><p>${T('已计入校园步行','Includes campus walking')}: ${last} min · ${T('天气余量','Weather buffer')}: ${weather} min</p>${$('accessible').checked?'<p>'+T('无障碍状态未核验：请联系校园支持确认电梯、坡道及入口。','Accessibility unverified: confirm lifts, ramps and entrances with campus support.')+'</p>':''}`;
$('routes').innerHTML=rows.map(r=>`<article class="route-card" data-mode="${r.id}" data-unavailable="${!!r.problem}" style="margin-top:10px;border-left:4px solid ${r.problem?'#ca7755':'#19734e'}"><b>${r.name}</b><p>${r.problem||clock(r.leave)+' → '+clock(r.arrive)+' · '+r.duration+' min'}</p></article>`).join('');$('buildingNote').textContent=`${b[0]} · ${EN?b[1]:b[2]+' / '+b[1]} · ${b[3]} Zone. `+T('先确认校园入口或 University Station，再根据地图找到建筑编号。校园步行时间是示例，尚未核验无障碍或入口开放情况。','Locate the campus entrance or University Station, then find the building code on the map. Campus walking time is illustrative; accessibility and entrance opening are unverified.');}
const publicOption=new Option(T('公交车、火车优先','Bus and train first'),'public',true,true);$('preference').prepend(publicOption);
const entryNote=document.createElement('p');entryNote.textContent=T('Munrow 暂按 R25 Munrow Lecture Theatre；Aston Webb 请确认 Great Hall、Student Hub、B Block 或其他分区。所有实际入口仍待核验。','Munrow provisionally means R25 Munrow Lecture Theatre. For Aston Webb, confirm Great Hall, Student Hub, B Block or another section. Actual entrances remain unverified.');$('building').parentElement.after(entryNote);
$('commute').onsubmit=e=>{e.preventDefault();update()};update();
